import math
from functools import reduce

def prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def calculate_a_n(n):
    # a_n = 6^n + 2^n + 3^n - 1
    return 6**n + 2**n + 3**n - 1

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

# 1. Calculate the first 15 terms and factorize them
terms = []
for n in range(1, 16):
    a_n = calculate_a_n(n)
    factors = prime_factorization(a_n)
    terms.append((a_n, factors))

print("--- First 15 terms and their factorizations ---")
for n, (a_n, factors) in enumerate(terms, 1):
    factor_str = " * ".join([f"{p}^{e}" for p, e in sorted(factors.items())])
    print(f"a_{n} = {a_n} = {factor_str}")

# 2. Calculate the GCD of the 15 terms
if terms:
    initial_gcd = terms[0][0]
    all_gcds = [initial_gcd]
    for i in range(1, len(terms)):
        next_gcd = gcd(all_gcds[-1], terms[i][0])
        all_gcds.append(next_gcd)

    final_gcd = all_gcds[-1]
    print("\n--- GCD Calculation ---")
    print(f"The GCD of a_1 through a_15 is: {final_gcd}")
else:
    print("No terms calculated.")
